const query = $input.first().json.query;
const VERIFY_TOKEN = 'VOTRE_META_VERIFY_TOKEN';
if (query['hub.mode'] === 'subscribe' && query['hub.verify_token'] === VERIFY_TOKEN) {
  return [{ json: { challenge: query['hub.challenge'], valid: true } }];
}
return [{ json: { valid: false, challenge: '' } }];

const body = $input.first().json.body;
try {
  const entry = body.entry?.[0];
  const value = entry?.changes?.[0]?.value;
  const messages = value?.messages;
  if (!messages || messages.length === 0) return [{ json: { skip: true, reason: 'Pas de message' } }];
  const message = messages[0];
  const contact = value.contacts?.[0];
  const phoneNumberId = value.metadata?.phone_number_id;
  const from = message.from;
  const fromName = contact?.profile?.name || 'Artisan';
  const msgType = message.type;
  const messageAge = Date.now() - parseInt(message.timestamp) * 1000;
  if (messageAge > 5 * 60 * 1000) return [{ json: { skip: true, reason: 'Message trop ancien' } }];
  let audioId = null, textContent = null, audioMimeType = 'audio/ogg';
  if (msgType === 'audio' || msgType === 'voice') {
    audioId = message.audio?.id || message.voice?.id;
    audioMimeType = message.audio?.mime_type || message.voice?.mime_type || 'audio/ogg';
  } else if (msgType === 'text') {
    textContent = message.text.body;
    if (textContent.trim().split(' ').length < 4) return [{ json: { skip: true, reason: 'Message trop court', from, phoneNumberId, tooShort: true } }];
  } else {
    return [{ json: { skip: true, reason: 'Type non supporte: ' + msgType, from, phoneNumberId, unsupportedType: true } }];
  }
  return [{ json: { skip: false, from, fromName, msgType, audioId, audioMimeType, textContent, phoneNumberId } }];
} catch (e) {
  return [{ json: { skip: true, reason: 'Erreur parsing: ' + e.message } }];
}

const data = $input.first().json;
if (!data.from || !data.phoneNumberId) return [];
let msg = '';
if (data.tooShort) msg = 'Bonjour ! Pour generer un devis, decrivez votre chantier en quelques phrases : type de travaux, surface, materiaux... Je m\'occupe du reste !';
else if (data.unsupportedType) msg = 'Je ne peux traiter que les messages vocaux ou texte. Envoyez-moi un vocal ou decrivez votre chantier par ecrit !';
if (!msg) return [];
return [{ json: { ...data, helpMessage: msg } }];

const audioData = $input.first().binary?.data;
const prevData = $('Parser message WhatsApp').first().json;
const base64Audio = audioData ? audioData.toString('base64') : '';
return [{ json: { ...prevData, base64Audio, mimeType: prevData.audioMimeType || 'audio/ogg', hasAudio: base64Audio.length > 0 } }];

const data = $input.first().json;
const WHATSAPP_TOKEN = 'VOTRE_WHATSAPP_TOKEN';
try {
  await $helpers.httpRequest({
    method: 'POST',
    url: `https://graph.facebook.com/v18.0/${data.phoneNumberId}/messages`,
    headers: { 'Authorization': `Bearer ${WHATSAPP_TOKEN}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ messaging_product: 'whatsapp', to: data.from, type: 'text', text: { body: 'Preparation de votre devis en cours (environ 20 secondes)...\n\nVos donnees sont traitees conformement au RGPD.' } })
  });
} catch (e) { /* non bloquant */ }
return [{ json: data }];

const data = $input.first().json;
const today = new Date().toLocaleDateString('fr-FR', { day: '2-digit', month: '2-digit', year: 'numeric' });
const devisNum = 'DEV-' + new Date().getFullYear() + '-' + String(new Date().getMonth() + 1).padStart(2, '0') + '-' + Date.now().toString().slice(-4);
const systemPrompt = `Tu es un expert devis pour artisans BTP francais.\nL artisan ${data.fromName} (tel: ${data.from}) decrit un chantier.\nDATE: ${today} | NUMERO: ${devisNum}\nREGLES: Prix marche francais 2024. TVA 10% renovation, 20% neuf, 0% si franchise.\nReponds UNIQUEMENT en JSON brut sans markdown.\nSTRUCTURE EXACTE:\n{"transcription":"[resume]","devis":{"numero":"${devisNum}","date":"${today}","validite":"30 jours","artisan":{"nom":"${data.fromName}","telephone":"${data.from}","regime_tva":"normal"},"client":{"nom":"A completer","adresse":"A completer","code_postal":"A completer","ville":"A completer","email":"A completer"},"description_chantier":"[description]","lignes":[{"designation":"[prestation]","quantite":1,"unite":"forfait","prix_unitaire_ht":0,"total_ht":0}],"sous_total_ht":0,"tva_taux":10,"tva_montant":0,"total_ttc":0,"conditions":"Acompte 30% commande. Solde reception travaux. Valable 30 jours.","notes":""}}`;
let userContent;
if (data.hasAudio && data.base64Audio) {
  userContent = [{ inlineData: { mimeType: data.mimeType || 'audio/ogg', data: data.base64Audio } }, { text: systemPrompt }];
} else {
  userContent = [{ text: systemPrompt + '\n\nDESCRIPTION ARTISAN:\n' + (data.textContent || '') }];
}
return [{ json: { ...data, devisNum, geminiPayload: { contents: [{ parts: userContent }], generationConfig: { temperature: 0.2, maxOutputTokens: 4096 } } } }];

const item = $input.first().json;
const prevData = $('Construire prompt Gemini').first().json;
let rawText = '';
try { rawText = item.candidates[0].content.parts[0].text; }
catch (e) { return [{ json: { error: true, message: 'Gemini n a pas repondu correctement. Reessayez.' } }]; }
let cleanJson = rawText.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
const firstBrace = cleanJson.indexOf('{');
const lastBrace = cleanJson.lastIndexOf('}');
if (firstBrace === -1) return [{ json: { error: true, message: 'Reponse invalide. Decrivez plus precisement le chantier.' } }];
cleanJson = cleanJson.substring(firstBrace, lastBrace + 1);
let parsed;
try { parsed = JSON.parse(cleanJson); }
catch (e) { return [{ json: { error: true, message: 'Erreur format. Reessayez avec une description plus claire.' } }]; }
const devis = parsed.devis;
const transcription = parsed.transcription || '';
let sousTotal = 0;
if (devis.lignes && Array.isArray(devis.lignes)) {
  devis.lignes = devis.lignes.map(l => {
    const qte = parseFloat(l.quantite) || 1;
    const pu = parseFloat(l.prix_unitaire_ht) || 0;
    const total = Math.round(qte * pu * 100) / 100;
    sousTotal += total;
    return { ...l, quantite: qte, prix_unitaire_ht: pu, total_ht: total };
  });
}
sousTotal = Math.round(sousTotal * 100) / 100;
const estFranchise = devis.artisan?.regime_tva === 'franchise';
const tvaTaux = estFranchise ? 0 : (parseFloat(devis.tva_taux) || 10);
const tvaMontant = estFranchise ? 0 : Math.round(sousTotal * (tvaTaux / 100) * 100) / 100;
const totalTTC = Math.round((sousTotal + tvaMontant) * 100) / 100;
devis.sous_total_ht = sousTotal; devis.tva_taux = tvaTaux; devis.tva_montant = tvaMontant; devis.total_ttc = totalTTC;
const lignesHTML = (devis.lignes || []).map((l, i) => `<tr style="background:${i % 2 === 0 ? '#fff' : '#f9f9f9'}"><td style="padding:10px 14px;border-bottom:1px solid #eee;font-size:14px;">${l.designation}</td><td style="padding:10px 14px;border-bottom:1px solid #eee;text-align:center;font-size:14px;">${l.quantite}</td><td style="padding:10px 14px;border-bottom:1px solid #eee;text-align:center;font-size:13px;color:#666;">${l.unite}</td><td style="padding:10px 14px;border-bottom:1px solid #eee;text-align:right;font-size:14px;">${parseFloat(l.prix_unitaire_ht).toFixed(2)} euro</td><td style="padding:10px 14px;border-bottom:1px solid #eee;text-align:right;font-size:14px;font-weight:600;">${parseFloat(l.total_ht).toFixed(2)} euro</td></tr>`).join('');
const mentionTVA = estFranchise ? '<p style="font-size:12px;color:#e65100;margin:0 0 16px;"><strong>TVA non applicable - article 293 B du CGI</strong></p>' : '';
const htmlDevis = `<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><title>Devis ${devis.numero}</title></head><body style="font-family:Arial,sans-serif;max-width:820px;margin:0 auto;padding:32px 24px;color:#1a1a1a;"><table style="width:100%;margin-bottom:28px;"><tr><td><h1 style="margin:0;font-size:36px;font-weight:700;">DEVIS</h1><p style="margin:4px 0 0;font-size:13px;color:#888;">KC Peak IA</p></td><td style="text-align:right;"><p style="margin:0;font-size:17px;font-weight:600;">N deg ${devis.numero}</p><p style="margin:4px 0;font-size:13px;color:#555;">Date : <strong>${devis.date}</strong></p><p style="margin:4px 0;font-size:13px;color:#555;">Valable 30 jours</p></td></tr></table><table style="width:100%;margin-bottom:24px;"><tr><td style="width:48%;background:#f5f5f5;padding:16px;border-radius:8px;"><p style="margin:0 0 6px;font-size:10px;font-weight:700;color:#888;text-transform:uppercase;">Artisan</p><p style="margin:0 0 4px;font-size:15px;font-weight:700;">${devis.artisan.nom}</p><p style="margin:0;font-size:13px;color:#555;">Tel : ${devis.artisan.telephone}</p></td><td style="width:4%;"></td><td style="width:48%;background:#f5f5f5;padding:16px;border-radius:8px;"><p style="margin:0 0 6px;font-size:10px;font-weight:700;color:#888;text-transform:uppercase;">Client</p><p style="margin:0 0 4px;font-size:15px;font-weight:700;">${devis.client.nom}</p><p style="margin:2px 0;font-size:13px;color:#555;">${devis.client.adresse}, ${devis.client.code_postal} ${devis.client.ville}</p>${devis.client.email !== 'A completer' ? `<p style="margin:2px 0;font-size:13px;color:#555;">${devis.client.email}</p>` : ''}</td></tr></table><div style="background:#fff8e1;border-left:4px solid #ffc107;padding:13px;border-radius:4px;margin-bottom:16px;"><strong>Objet :</strong> ${devis.description_chantier}</div>${mentionTVA}<table style="width:100%;border-collapse:collapse;margin-bottom:24px;"><thead><tr style="background:#1a1a1a;color:#fff;"><th style="padding:12px 14px;text-align:left;font-size:13px;">Designation</th><th style="padding:12px 14px;text-align:center;font-size:13px;">Qte</th><th style="padding:12px 14px;text-align:center;font-size:13px;">Unite</th><th style="padding:12px 14px;text-align:right;font-size:13px;">P.U. HT</th><th style="padding:12px 14px;text-align:right;font-size:13px;">Total HT</th></tr></thead><tbody>${lignesHTML}</tbody></table><table style="margin-left:auto;min-width:280px;border-collapse:collapse;margin-bottom:28px;"><tr><td style="padding:8px 16px;font-size:14px;color:#555;">Sous-total HT</td><td style="padding:8px 16px;font-size:14px;font-weight:600;text-align:right;">${sousTotal.toFixed(2)} euro</td></tr><tr><td style="padding:8px 16px;font-size:14px;color:#555;">TVA (${tvaTaux}%)</td><td style="padding:8px 16px;font-size:14px;text-align:right;">${tvaMontant.toFixed(2)} euro</td></tr><tr style="background:#1a1a1a;color:#fff;"><td style="padding:13px 16px;font-size:16px;font-weight:700;">TOTAL TTC</td><td style="padding:13px 16px;font-size:20px;font-weight:700;text-align:right;">${totalTTC.toFixed(2)} euro</td></tr></table><div style="background:#f5f5f5;padding:16px;border-radius:8px;margin-bottom:20px;"><p style="margin:0 0 6px;font-size:14px;font-weight:600;">Conditions</p><p style="margin:0;font-size:13px;color:#555;">${devis.conditions}</p></div><div style="border:2px dashed #ddd;padding:20px;border-radius:8px;text-align:center;"><p style="margin:0 0 8px;font-size:13px;color:#666;">Bon pour accord - Date : ___________</p><p style="margin:0;font-size:13px;color:#666;">Signature : _________________________</p></div><p style="text-align:center;color:#ccc;font-size:11px;margin-top:24px;">Devis genere par KC Peak IA - ${devis.date} - Conforme RGPD</p></body></html>`;
return [{ json: { ...prevData, transcription, devis, htmlDevis, estFranchise, error: false } }];

